#include <set>
#include <iostream>

struct CustomType { int id; };

struct CustomLess {
    bool operator()(const CustomType& a, const CustomType& b) const {
        return a.id < b.id; // Defines ordering
    }
};

int main() {
    std::set<CustomType, CustomLess> s;
    s.insert({10});

    // Element B is equivalent to A because !(10 < 10) && !(10 < 10)
    // The set only holds one element with id 10, regardless of other fields.
    s.insert({10}); 

    // Output: Size is 1, proving equivalence is determined by CustomLess.
    std::cout << "Set size: " << s.size() << std::endl;
}
